// reproduce-pipeline-bug.js
const prettier = require("prettier");

// This input uses the smart-pipeline placeholder `#`
const smartInput = `5 |> # * 2`;

// Load the pipeline syntax plugin bundled with Prettier
// (In v1.17.1 it lives in the main package under the hood)

try {
  const output = prettier.format(smartInput, {
    parser: "babel",
    plugins: [require("@babel/plugin-syntax-pipeline-operator")],
    // Enable the smart pipeline proposal
    pipelineProposal: "smart",
  });
  console.log(output);
} catch (err) {
  console.error("Error formatting smart pipeline input:", err.message);
}

// Contrast: minimal pipeline syntax (no `#`) works without error
const minimalInput = `5 |> double`;
const minimalOutput = prettier.format(minimalInput, {
  parser: "babel",
  plugins: [require("@babel/plugin-syntax-pipeline-operator")],
  pipelineProposal: "minimal",
});
console.log("Minimal pipeline formats as:", minimalOutput);
